from __future__ import annotations

import re
from datetime import date
from pathlib import Path

import pandas as pd
import pytesseract
from PIL import Image, ImageFilter, ImageOps

IMG_DIR = Path('/app/workspace/dataset/img')
OUT_XLSX = Path('/app/workspace/stat_ocr.xlsx')

EXCLUSION_KEYWORDS = [
    'SUBTOTAL',
    'SUB TOTAL',
    'TAX',
    'GST',
    'SST',
    'DISCOUNT',
    'CHANGE',
    'CASH TENDERED',
]

PRIORITY_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL', 'TOTAL', 'AMOUNT'],
]

AMOUNT_RE = re.compile(r'(?:\b\d{1,3}(?:,\d{3})+(?:[\.,]\d{2})\b|\b\d+(?:[\.,]\d{2})\b|\b\d+\b)')

DATE_PATTERNS = [
    re.compile(r'(?P<y>(?:19|20)\d{2})[\-/\.](?P<m>\d{1,2})[\-/\.](?P<d>\d{1,2})'),
    re.compile(r'(?P<d>\d{1,2})[\-/\.](?P<m>\d{1,2})[\-/\.](?P<y>(?:19|20)\d{2}|\d{2})'),
]


def _preprocess_variants(img: Image.Image) -> list[Image.Image]:
    gray = ImageOps.grayscale(img)
    gray = ImageOps.autocontrast(gray)
    gray = gray.filter(ImageFilter.SHARPEN)

    inv = ImageOps.invert(gray)

    return [gray, inv]


def _ocr_best_effort(img_path: Path) -> list[str]:
    img = Image.open(img_path)
    variants = _preprocess_variants(img)
    texts: list[str] = []

    # Try a small deterministic set of configs; stop early if enough.
    configs = ['--psm 6', '--psm 4']
    for variant in variants:
        for cfg in configs:
            texts.append(pytesseract.image_to_string(variant, config=cfg))
    return texts


def _parse_date(text: str) -> str | None:
    # Preserve text order by iterating finditer across patterns.
    for pat in DATE_PATTERNS:
        for m in pat.finditer(text):
            try:
                y = m.group('y')
                year = int(y)
                if len(y) == 2:
                    yy = int(y)
                    year = 2000 + yy if yy <= 69 else 1900 + yy

                month = int(m.group('m'))
                day = int(m.group('d'))
                d = date(year, month, day)
                if 1990 <= d.year <= 2035:
                    return d.isoformat()
            except Exception:
                continue
    return None


def _normalize_amount_token(tok: str) -> str | None:
    s = tok.strip()

    # Handle thousands separators vs decimal comma.
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        # If last group is exactly 2 digits, treat as decimal comma.
        parts = s.split(',')
        if len(parts) == 2 and len(parts[1]) == 2:
            s = parts[0] + '.' + parts[1]
        else:
            s = s.replace(',', '')

    # Now must be a number.
    try:
        value = float(s)
    except Exception:
        return None

    # Heuristic: totals are rarely 0.00.
    if value < 0:
        return None

    return f'{value:.2f}'


def _extract_last_amount_from_line(line: str) -> str | None:
    matches = AMOUNT_RE.findall(line)
    if not matches:
        return None

    # Prefer the last token on the line.
    for tok in reversed(matches):
        norm = _normalize_amount_token(tok)
        if norm is not None:
            return norm
    return None


def _line_has_exclusion(line_upper: str) -> bool:
    return any(k in line_upper for k in EXCLUSION_KEYWORDS)


def _extract_total(text: str) -> str | None:
    lines = [ln.strip() for ln in text.splitlines()]
    lines = [ln for ln in lines if ln]
    uppers = [ln.upper() for ln in lines]

    for group in PRIORITY_GROUPS:
        # Scan from bottom upwards to prefer the final total.
        for i in range(len(lines) - 1, -1, -1):
            u = uppers[i]
            if _line_has_exclusion(u):
                continue
            if not any(k in u for k in group):
                continue

            amt = _extract_last_amount_from_line(lines[i])
            if amt is not None:
                return amt

            # Fallback: amount might be on the next line.
            if i + 1 < len(lines):
                amt2 = _extract_last_amount_from_line(lines[i + 1])
                if amt2 is not None:
                    return amt2

    return None


def extract_fields_for_image(img_path: Path) -> tuple[str | None, str | None]:
    date_val = None
    total_val = None

    for t in _ocr_best_effort(img_path):
        if date_val is None:
            date_val = _parse_date(t)
        if total_val is None:
            total_val = _extract_total(t)
        if date_val is not None and total_val is not None:
            break

    return date_val, total_val


def main() -> None:
    img_files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'}])

    rows = []
    for p in img_files:
        d, total = extract_fields_for_image(p)
        rows.append({
            'filename': p.name,
            'date': d,
            'total_amount': total,
        })

    df = pd.DataFrame(rows, columns=['filename', 'date', 'total_amount'])
    OUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
    df.to_excel(OUT_XLSX, index=False, sheet_name='results')


if __name__ == '__main__':
    main()
    print(f'Wrote {OUT_XLSX}')
