                    year = 2000 + yy if yy <= 69 else 1900 + yy
                month = int(m.group('m'))
                day = int(m.group('d'))
                d = date(year, month, day)
                if 1990 <= d.year <= 2035:
                    return d.isoformat()
            except Exception:
                continue
    return None
def line_has_exclusion(line_upper: str) -> bool:
    return any(k in line_upper for k in EXCLUSION_KEYWORDS)
def normalize_amount_token(tok: str):
    s = tok.strip()
    if ',' in s and '.' in s:
        s = s.replace(',', '')
    elif ',' in s and '.' not in s:
        parts = s.split(',')
        if len(parts) == 2 and len(parts[1]) == 2:
            s = parts[0] + '.' + parts[1]
        else:
            s = s.replace(',', '')
    try:
        v = float(s)
    except Exception:
        return None
    if v < 0:
        return None
    return f'{v:.2f}'
def extract_last_amount_from_line(line: str):
    matches = AMOUNT_RE.findall(line)
    if not matches:
        return None
    for tok in reversed(matches):
        norm = normalize_amount_token(tok)
        if norm is not None:
            return norm
    return None
def extract_total(text: str):
    lines = [ln.strip() for ln in text.splitlines()]
    lines = [ln for ln in lines if ln]
    uppers = [ln.upper() for ln in lines]
    for group in PRIORITY_GROUPS:
        for i in range(len(lines) - 1, -1, -1):
            u = uppers[i]
            if line_has_exclusion(u):
                continue
            if not any(k in u for k in group):
                continue
            amt = extract_last_amount_from_line(lines[i])
            if amt is not None:
                return amt
            if i + 1 < len(lines):
                amt2 = extract_last_amount_from_line(lines[i + 1])
                if amt2 is not None:
                    return amt2
    return None
def extract_fields(img_path: Path):
    d = None
    t = None
    for text in ocr_texts(img_path):
        if d is None:
            d = parse_date(text)
        if t is None:
            t = extract_total(text)
        if d is not None and t is not None:
            break
    return d, t
def main():
    img_files = sorted([p for p in IMG_DIR.iterdir() if p.is_file() and p.suffix.lower() in {'.jpg', '.jpeg', '.png', '.webp'}])
    wb = Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for p in img_files:
        d, t = extract_fields(p)
        ws.append([p.name, d, t])
    # Ensure only one sheet.
    for s in list(wb.sheetnames):
        if s != 'results':
            wb.remove(wb[s])
    OUT_XLSX.parent.mkdir(parents=True, exist_ok=True)
    wb.save(OUT_XLSX)
    # Validate: exactly one sheet + correct header order.
    wb2 = load_workbook(OUT_XLSX)
    assert wb2.sheetnames == ['results']
    ws2 = wb2['results']
    header = [ws2.cell(row=1, column=i).value for i in range(1, 4)]
    assert header == ['filename', 'date', 'total_amount']
if __name__ == '__main__':
    main()
    print('OK:', OUT_XLSX)
